#!/bin/bash
# RLinear on Solar: input 96, horizons 96 192 336 720; settings of the official scripts, protocol of the official loaders.
# Generated by scripts/multivariate_forecasting/make_scripts.py: change the profile and generate again.
#   bash scripts/multivariate_forecasting/SolarEnergy/RLinear.sh                                   seeds 2021 2022 2023
#   SEEDS="2021" EXTRA_ARGS="--no_use_gpu --num_workers 0" bash scripts/multivariate_forecasting/SolarEnergy/RLinear.sh   one seed on the CPU
# Results: output/long_term_forecast/Solar.tsv (one row per run); checkpoints: temp/checkpoints/Solar/.
export CUDA_VISIBLE_DEVICES=${CUDA_VISIBLE_DEVICES:-0}
cd "$(dirname "$0")/../../.."
root="$(python -m src.utils.paths root solar_AL.txt)/"
seeds=(${SEEDS:-2021 2022 2023})

# horizon 96: scripts/benchmark/official/RLinear/script.md (ECL configuration)
for seed in "${seeds[@]}"; do
  python -u scripts/run.py \
    --is_training 1 \
    --model RLinear \
    --des Solar_96_RLinear \
    --seed "$seed" \
    --root_path "$root" \
    --data_path solar_AL.txt \
    --data Solar \
    --model_id Solar_96_96 \
    --features M \
    --seq_len 96 \
    --label_len 48 \
    --pred_len 96 \
    --enc_in 137 \
    --dec_in 137 \
    --c_out 137 \
    --freq h \
    --drop_last \
    --test_batch_size 1 \
    --no_time_marks \
    --learning_rate 0.001 \
    --batch_size 16 \
    --dropout 0 \
    --train_epochs 15 \
    --patience 10 \
    $EXTRA_ARGS
done

